cd /work && node - <<'EOF'
const YAML = require('/usr/local/lib/node_modules/@earendil-works/pi-coding-agent/node_modules/yaml');
const fs = require('fs');
const src = fs.readFileSync('source.md','utf8');
const ids = ['bean-001','bean-002','bean-003'];
const seen = new Set();
const paths = {};
const required = ['schema_version','id','repo','title','intent','status','allowed_write_paths','acceptance_criteria','definition_of_done'];
let fail = 0;
const err = (m)=>{ console.log('FAIL: '+m); fail++; };
for (const id of ids) {
  const f = `intake/drafts/${id}.yaml`;
  const b = YAML.parse(fs.readFileSync(f,'utf8'));
  for (const r of required) if (!(r in b)) err(`${f}: missing ${r}`);
  if (b.schema_version !== 'bean/2.0.0') err(`${f}: schema_version`);
  if (b.id !== id) err(`${f}: id/file mismatch`);
  if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(b.repo)) err(`${f}: repo`);
  if (b.repo !== 'beekeeper-lab/tic-tac-toe-py') err(`${f}: repo value ${b.repo}`);
  if (b.status !== 'draft') err(`${f}: status`);
  if ('approval' in b) err(`${f}: has approval`);
  const s = b.source;
  if (!s || s.kind!=='transcript' || s.ref!=='source.md' || s.date!=='2026-09-30') err(`${f}: source block`);
  if (!src.includes(s.excerpt)) err(`${f}: excerpt not in source.md: ${s.excerpt}`);
  b.acceptance_criteria.forEach((ac,i)=>{
    if (!/^ac[0-9]+$/.test(ac.id)) err(`${f}: ac id ${ac.id}`);
    if (!ac.text) err(`${f}: ac ${ac.id} text`);
    const v = ac.verify;
    const keys = new Set(Object.keys(v));
    for (const k of keys) if (!['kind','run','test_id','gate_id','rubric','note'].includes(k)) err(`${f}: ac ${ac.id} verify key ${k}`);
    if (!['command','test','manual','gate','judge'].includes(v.kind)) err(`${f}: ac ${ac.id} kind`);
    if (v.kind==='test' && !/\.py::test_/.test(v.test_id)) err(`${f}: ac ${ac.id} test_id`);
    if (v.kind==='manual' && !v.note) err(`${f}: ac ${ac.id} manual needs note`);
  });
  for (const p of b.allowed_write_paths) (paths[p] = paths[p]||[]).push(id);
  for (const d of (b.dependencies||[])) { if (!seen.has(d)) err(`${f}: dep ${d} not earlier`); }
  seen.add(id);
  for (const c of (b.constraints||[])) { const t = typeof c==='string'?c:c.text; if(!t) err(`${f}: constraint without text`); }
  for (const ng of (b.non_goals||[])) { const t = typeof ng==='string'?ng:ng.text; if(!t) err(`${f}: non_goal without text`); }
  console.log(f+': OK');
}
const shared = Object.entries(paths).filter(([,v])=>v.length>1);
console.log('shared write paths:', shared.length? JSON.stringify(shared) : 'none');
console.log(fail ? fail+' FAILURES' : 'ALL CHECKS PASSED');
process.exit(fail?1:0);
EOF

